using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using FluentFTP.Client.BaseClient;
using Xunit;

namespace FluentFTP.Tests.Unit {
	/// <summary>
	/// Warning: This class is generated by Claude in Oct 2026, and may be extraneous, excessive,
	/// overly complicated, logically incorrect and may contain logical fallacies.
	///
	/// A client that opens its own sockets (as it would through an SSH jump host) and hands them to
	/// FtpSocketStream.Connect(Socket): the server name is never resolved by FluentFTP, and both the
	/// control and the data connections go through the client's own connector.
	/// </summary>
	public class ConnectedSocketTests {
		// .invalid never resolves (RFC 6761): any DNS lookup by FluentFTP would fail the test.
		private const string UnresolvableHost = "ftp.invalid";
		private const int NominalPort = 2121;

		[Theory]
		[InlineData(false, FtpDataConnectionType.EPSV)]
		[InlineData(false, FtpDataConnectionType.PASVEX)]
		[InlineData(true, FtpDataConnectionType.EPSV)]
		[InlineData(true, FtpDataConnectionType.PASVEX)]
		public async Task ControlAndDataConnectionsUseTheProvidedSockets(bool asynchronous, FtpDataConnectionType type) {
			using var deadline = new CancellationTokenSource(TimeSpan.FromSeconds(30));
			using var server = new LoopbackFtpServer(deadline.Token);
			var connector = new Connector(server.Port);
			using BaseFtpClient client = asynchronous ? new ConnectorAsyncFtpClient(connector) : new ConnectorFtpClient(connector);
			client.Config.DataConnectionType = type;
			client.Config.ConnectTimeout = client.Config.ReadTimeout = 5000;
			client.Config.DataConnectionConnectTimeout = client.Config.DataConnectionReadTimeout = 5000;

			var downloaded = await Download(client, server.Payload.Length, deadline.Token);
			await server.Completion.WaitAsync(deadline.Token);

			Assert.Equal(server.Payload, downloaded);
			Assert.Equal(new[] {
				(UnresolvableHost, NominalPort),
				(UnresolvableHost, server.DataPort),
			}, connector.Requests);
		}

		[Fact]
		public void NullSocketIsRejected() {
			using var client = new FtpClient(UnresolvableHost);
			using var stream = new FtpSocketStream(client);

			Assert.Throws<ArgumentNullException>(() => stream.Connect((Socket)null!));
			Assert.False(stream.IsConnected);
		}

		[Fact]
		public void UnconnectedSocketIsRejected() {
			using var client = new FtpClient(UnresolvableHost);
			using var stream = new FtpSocketStream(client);
			using var socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);

			Assert.Throws<ArgumentException>(() => stream.Connect(socket));
			Assert.False(stream.IsConnected);
		}

		private static async Task<byte[]> Download(BaseFtpClient client, int length, CancellationToken token) {
			using var received = new MemoryStream();
			if (client is AsyncFtpClient asyncClient) {
				await asyncClient.Connect(token);
				var stream = (FtpDataStream)await asyncClient.OpenRead("/download.bin", FtpDataType.Binary, 0, length, token);
				await stream.CopyToAsync(received, token);
				await stream.CloseAsync(token);
				await asyncClient.Disconnect(token);
			}
			else {
				var syncClient = (FtpClient)client;
				syncClient.Connect();
				var stream = (FtpDataStream)syncClient.OpenRead("/download.bin", FtpDataType.Binary, 0, length);
				stream.CopyTo(received);
				stream.Close();
				syncClient.Disconnect();
			}
			return received.ToArray();
		}

		/// <summary>
		/// Stands for a jump host: records the requested destination and opens a loopback connection to the
		/// test server instead (its real control port, or the data port the server announced).
		/// </summary>
		private sealed class Connector {
			private readonly int m_controlPort;
			private readonly List<(string Host, int Port)> m_requests = new List<(string Host, int Port)>();

			internal Connector(int controlPort) {
				m_controlPort = controlPort;
			}

			internal IReadOnlyList<(string Host, int Port)> Requests {
				get {
					lock (m_requests) {
						return m_requests.ToArray();
					}
				}
			}

			internal Socket Connect(string host, int port) {
				lock (m_requests) {
					m_requests.Add((host, port));
				}
				var socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
				socket.Connect(IPAddress.Loopback, port == NominalPort ? m_controlPort : port);
				return socket;
			}

			internal async Task<Socket> ConnectAsync(string host, int port, CancellationToken token) {
				lock (m_requests) {
					m_requests.Add((host, port));
				}
				var socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
				await socket.ConnectAsync(IPAddress.Loopback, port == NominalPort ? m_controlPort : port, token);
				return socket;
			}
		}

		private sealed class ConnectorFtpClient : FtpClient {
			private readonly Connector m_connector;

			internal ConnectorFtpClient(Connector connector) : base(UnresolvableHost, "test-user", "test-password", NominalPort) {
				m_connector = connector;
			}

			protected override void Connect(FtpSocketStream stream) {
				stream.Connect(m_connector.Connect(Host, Port));
			}

			protected override void Connect(FtpSocketStream stream, string host, int port, FtpIpVersion ipVersions) {
				stream.Connect(m_connector.Connect(host, port));
			}
		}

		private sealed class ConnectorAsyncFtpClient : AsyncFtpClient {
			private readonly Connector m_connector;

			internal ConnectorAsyncFtpClient(Connector connector) : base(UnresolvableHost, "test-user", "test-password", NominalPort) {
				m_connector = connector;
			}

			protected override async Task ConnectAsync(FtpSocketStream stream, CancellationToken token) {
				stream.Connect(await m_connector.ConnectAsync(Host, Port, token));
			}

			protected override async Task ConnectAsync(FtpSocketStream stream, string host, int port, FtpIpVersion ipVersions, CancellationToken token) {
				stream.Connect(await m_connector.ConnectAsync(host, port, token));
			}
		}

		/// <summary>
		/// Serves one plain FTP control connection. RETR sends the payload over an EPSV or PASV data connection;
		/// the PASV reply advertises an address the client must not use.
		/// </summary>
		private sealed class LoopbackFtpServer : IDisposable {
			private readonly TcpListener m_listener = new TcpListener(IPAddress.Loopback, 0);
			private TcpListener? m_dataListener;

			internal LoopbackFtpServer(CancellationToken token) {
				m_listener.Start();
				Completion = Task.Run(() => Serve(token));
			}

			internal byte[] Payload { get; } = RandomNumberGenerator.GetBytes(65537);
			internal int Port => ((IPEndPoint)m_listener.LocalEndpoint).Port;
			internal int DataPort { get; private set; }
			internal Task Completion { get; }

			private int OpenDataListener() {
				m_dataListener = new TcpListener(IPAddress.Loopback, 0);
				m_dataListener.Start();
				DataPort = ((IPEndPoint)m_dataListener.LocalEndpoint).Port;
				return DataPort;
			}

			private async Task Serve(CancellationToken token) {
				using var peer = await m_listener.AcceptTcpClientAsync(token);
				var stream = peer.GetStream();
				var reader = new StreamReader(stream, Encoding.ASCII, false, 1024, true);
				var writer = new StreamWriter(stream, Encoding.ASCII, 1024, true) { AutoFlush = true, NewLine = "\r\n" };
				await writer.WriteLineAsync("220 Loopback FTP test");
				while (true) {
					var command = await reader.ReadLineAsync(token);
					if (command == null) {
						break;
					}
					var verb = command.Split(' ')[0];
					switch (verb) {
						case "EPSV":
							await writer.WriteLineAsync($"229 Entering Extended Passive Mode (|||{OpenDataListener()}|)");
							break;
						case "PASV":
							var port = OpenDataListener();
							await writer.WriteLineAsync($"227 Entering Passive Mode (192,0,2,1,{port >> 8},{port & 0xFF})");
							break;
						case "RETR":
							await writer.WriteLineAsync("150 Opening data connection");
							await ServeData(token);
							await writer.WriteLineAsync("226 Transfer complete");
							break;
						case "QUIT":
							await writer.WriteLineAsync("221 Goodbye");
							return;
						default:
							await writer.WriteLineAsync(GetResponse(verb));
							break;
					}
				}
			}

			private async Task ServeData(CancellationToken token) {
				var listener = m_dataListener ?? throw new InvalidOperationException("RETR without EPSV or PASV.");
				m_dataListener = null;
				try {
					using var peer = await listener.AcceptTcpClientAsync(token);
					await peer.GetStream().WriteAsync(Payload, token);
				}
				finally {
					listener.Stop();
				}
			}

			private static string GetResponse(string verb) => verb switch {
				"USER" => "331 Password required",
				"PASS" => "230 Logged in",
				"SYST" => "215 UNIX Type: L8",
				"PWD" => "257 \"/\"",
				"FEAT" => "500 No features",
				_ => "200 OK",
			};

			public void Dispose() {
				m_listener.Stop();
				m_dataListener?.Stop();
			}
		}
	}
}
